class EventAction(BaseModel):
    """Typed representation of the `EventAction` API schema."""

    model_config = ConfigDict(populate_by_name=False, arbitrary_types_allowed=True)

    name: str
    """Unique action name. Must be unique across all event actions."""
    type: EventActionTypes
    """
    Supported event action types. The value selects which sub-config inside `BaseEventActionOptions` is active; all other sub-configs are zeroed on save. Types marked **Premium** require a Premium-tier license.

      * `1` - HTTP → `options.http_config` (templated: `endpoint`, `body`, `headers[].value`, `query_parameters[].value`, `parts[].filepath`, `parts[].body`, `parts[].headers[].value`)
      * `2` - Command → `options.cmd_config` (templated: `args[]`, `env_vars[].value`). The binary must be allow-listed via `SFTPGO_HOOK__ENABLED_ACTION_COMMANDS`.
      * `3` - Email → `options.email_config` (templated: `recipients[]`, `bcc[]`, `subject`, `body`, `attachments[]`)
      * `4` - Backup (no sub-config)
      * `5` - User quota reset (no sub-config)
      * `6` - Folder quota reset (no sub-config)
      * `7` - Transfer quota reset (no sub-config)
      * `8` - Data retention check → `options.retention_config`. Populates `{{.RetentionChecks}}` for downstream actions in the same rule.
      * `9` - Filesystem → `options.fs_config`. The nested `fs_config.type` picks the sub-action (see `FilesystemActionTypes`).
      * `11` - Password expiration check → `options.pwd_expiration_config`
      * `12` - User expiration check (no sub-config)
      * `13` - Identity Provider account check → `options.idp_config` (**Premium**; templated: `template_user`, `template_admin` — each is a Go template that renders a full User/Admin JSON payload. Intended for just-in-time provisioning after OIDC login.)
      * `14` - User inactivity check → `options.user_inactivity_config`
      * `15` - Rotate log file (no sub-config)
      * `16` - IMAP → `options.imap_config` (**Premium**; templated: `email[]`, `subject`, `body`, `attachments[]`, `target_folder`)
      * `17` - ICAP → `options.icap_config` (**Premium**; templated: `paths[]`)
      * `18` - Share expiration check → `options.share_expiration_config`. Populates `{{.ShareExpirationChecks}}` for downstream actions.
      * `19` - Event report → `options.event_report_config` (**Premium**). Populates `{{.EventReports}}` for downstream email/HTTP actions.

    See the **[sftpgo](https://github.com/sftpgo/sftpgo-skill)** reference skill for the full template context, registered functions, and worked examples.
    """
    id: int | NotGiven = NOT_GIVEN
    """Optional `int32`-formatted value serialized in the `id` wire field."""
    description: str | NotGiven = NOT_GIVEN
    """Optional description of what the action does."""
    options: BaseEventActionOptions | NotGiven = NOT_GIVEN
    """
    Tagged union of action-specific sub-configurations. **Only the sub-object whose key matches the parent action's `type` is read**; the others are zeroed on save.
    Mapping (see `EventActionTypes`):
    type 1 → `http_config`, type 2 → `cmd_config`, type 3 → `email_config`, type 8 → `retention_config`,
    type 9 → `fs_config`, type 11 → `pwd_expiration_config`, type 13 → `idp_config`, type 14 → `user_inactivity_config`,
    type 16 → `imap_config`, type 17 → `icap_config`, type 18 → `share_expiration_config`, type 19 → `event_report_config`.
    Types 4, 5, 6, 7, 12, 15 have no sub-configuration.
    """
    rules: list[str] | NotGiven = NOT_GIVEN
    """Names of event rules referencing this action. Populated on read; ignored on write."""
    order: int | NotGiven = NOT_GIVEN
    """execution order"""
    relation_options: EventActionOptions | NotGiven = NOT_GIVEN
    """Optional object value serialized in the `relation_options` wire field."""

    @model_validator(mode="before")
    @classmethod
    def _validate_required(cls, value):
        validate_required(value, ["name", "type"])
        return value

    @field_validator("id")
    @classmethod
    def _validate_id(cls, value):
        validate_range("id", value, min=1)
        return value
